#!/usr/bin/env node
/**
 * Build pipeline — runs `tsc` against tsconfig.build.json, then copies
 * the non-TS assets that the compiler ignores:
 *
 *   - src/providers/deepseek/sha3_wasm.wasm  → dist/providers/deepseek/sha3_wasm.wasm
 *     (loaded at runtime by direct.ts via `import.meta.url + "sha3_wasm.wasm"`)
 *
 *   - scripts/extract-ai-token.mjs           → dist/scripts/extract-ai-token.mjs
 *     (spawned by tokenManager.ts. The path resolver in tokenManager probes
 *      both the source and the built layout — keep this offset stable.)
 *
 * Why a script instead of `cp` in the npm script?
 *   - Cross-platform (Windows / macOS / Linux) without shell glue
 *   - Single source of truth for what counts as "shippable"
 *   - Easy to extend when we add other providers with their own assets
 */
import { cp, mkdir, rm, stat } from "node:fs/promises";
import { existsSync }          from "node:fs";
import { spawn }               from "node:child_process";
import { dirname, join }       from "node:path";
import { fileURLToPath }       from "node:url";

const HERE = dirname(fileURLToPath(import.meta.url));
const ROOT = join(HERE, "..");
const DIST = join(ROOT, "dist");

/** Run a command, inheriting stdio, reject on non-zero exit. */
function run(cmd, args) {
  return new Promise((resolve, reject) => {
    const child = spawn(cmd, args, { cwd: ROOT, stdio: "inherit" });
    child.on("close", (code) => {
      code === 0 ? resolve() : reject(new Error(`${cmd} ${args.join(" ")} exited ${code}`));
    });
    child.on("error", reject);
  });
}

async function ensureExists(p, label) {
  if (!existsSync(p)) throw new Error(`${label} missing: ${p}`);
  const s = await stat(p);
  return s.size;
}

async function main() {
  console.log("[build] cleaning dist/");
  if (existsSync(DIST)) await rm(DIST, { recursive: true, force: true });

  console.log("[build] compiling typescript...");
  // Invoke tsc via the current Node binary + TypeScript's JS entrypoint.
  // This avoids the .cmd-shim mess on Windows (EINVAL since Node 18.20) AND
  // the DEP0190 "shell:true with args" deprecation that fires when going
  // through npx or the .bin shims.
  const tscEntry = join(ROOT, "node_modules", "typescript", "bin", "tsc");
  if (!existsSync(tscEntry)) {
    throw new Error(`typescript not installed locally — expected ${tscEntry}. Run \`npm install\` first.`);
  }
  await run(process.execPath, [tscEntry, "-p", "tsconfig.build.json"]);

  console.log("[build] copying assets...");
  const assets = [
    {
      src: join(ROOT, "src", "providers", "deepseek", "sha3_wasm.wasm"),
      dst: join(DIST, "providers", "deepseek", "sha3_wasm.wasm"),
      label: "DeepSeek PoW WASM",
    },
    {
      src: join(ROOT, "scripts", "extract-ai-token.mjs"),
      dst: join(DIST, "scripts", "extract-ai-token.mjs"),
      label: "Token-extract script",
    },
    {
      src: join(ROOT, "scripts", "extract-chatgpt-session.mjs"),
      dst: join(DIST, "scripts", "extract-chatgpt-session.mjs"),
      label: "ChatGPT session-setup script",
    },
  ];

  for (const a of assets) {
    const size = await ensureExists(a.src, a.label);
    await mkdir(dirname(a.dst), { recursive: true });
    await cp(a.src, a.dst);
    console.log(`  ${a.label}: ${size} bytes → ${a.dst.replace(ROOT, "").replace(/\\/g, "/")}`);
  }

  console.log("[build] verifying entry points...");
  for (const f of [
    "index.js",
    "index.d.ts",
    "providers/deepseek/index.js",
    "providers/deepseek/index.d.ts",
    "providers/deepseek/direct.js",
    "providers/deepseek/tokenManager.js",
    "providers/deepseek/sha3_wasm.wasm",
    "providers/chatgpt/index.js",
    "providers/chatgpt/index.d.ts",
    "providers/chatgpt/direct.js",
    "providers/chatgpt/transport.js",
    "scripts/extract-ai-token.mjs",
    "scripts/extract-chatgpt-session.mjs",
    "log/logger.js",
  ]) {
    const p = join(DIST, f);
    if (!existsSync(p)) throw new Error(`expected built artifact missing: ${p}`);
  }

  console.log("[build] done");
}

main().catch((err) => {
  console.error("[build] FAILED:", err.message);
  process.exitCode = 1;
});
